// Decides whether this run may try to take the run lease.
//
// The lease is a row (dedup_key "__run_lock__") in the alert-state Data Table, so it is shared by
// every execution - scheduled, manual, or running on another worker. Workflow static data cannot do
// that: it is only written back when an execution ends, so two overlapping runs overwrite each other.
//
// The lease is time-boxed, never explicitly released, so a crashed run can never leave the workflow
// permanently locked: the lease simply expires after `runLockMinutes`.
const cfg = $('Config').first().json;
const row = $input.all().map((i) => i.json).find((r) => r && r.dedup_key === '__run_lock__');

if (!row) {
  throw new Error(
    'Run-lock row not found in Data Table "servicenow_alert_state". ' +
      'Run the "ServiceNow Monitor - Setup" workflow once, then retry.'
  );
}

const now = Date.now();
const claimedAt = row.claimed_at ? new Date(row.claimed_at).getTime() : 0;
const leaseMs = Number(cfg.runLockMinutes) * 60 * 1000;

if (row.claim_id && claimedAt + leaseMs > now) {
  return []; // another run holds the lease - skip this cycle quietly
}

// Propose taking the lease. "Take Lock" applies it as a compare-and-swap on `version`, so if two
// runs get here at the same moment only one update matches and the other gets nothing back.
return [
  {
    json: {
      dedup_key: '__run_lock__',
      status: 'lock',
      claim_id: cfg.runId,
      claimed_at: new Date(now).toISOString(),
      version: Number(row.version || 0) + 1,
    },
  },
];

// "Take Lock" is a compare-and-swap, so it only returns the row if this run's update actually
// matched. Confirm the lease holder is us; otherwise another run won the race and we stop.
const cfg = $('Config').first().json;
const won = $input.all().some((i) => i.json && i.json.claim_id === cfg.runId);
if (!won) return [];
return [{ json: { runId: cfg.runId, lockAcquiredAt: new Date().toISOString() } }];

// Turns the (paginated) ServiceNow response into the list of alerts that currently apply.
// Always returns exactly ONE item so the rest of the run still executes when there are no alerts
// (that is when "close cleared alerts" matters most).
const cfg = $('Config').first().json;
const staleMs = Number(cfg.staleHours) * 3600 * 1000;
const pageSize = Number(cfg.pageSize);
const maxPages = Number(cfg.maxPages);
const now = Date.now();
const val = (f) => (f && typeof f === 'object' ? f.value : f);
const disp = (f) => (f && typeof f === 'object' ? f.display_value || f.value : f);
const CLOSED_STATES = ['6', '7', '8']; // Resolved, Closed, Canceled

// ---- 1. Collect every page --------------------------------------------------------------
const pages = $input.all();
const incidents = [];
const seen = new Set();
let lastPageLength = 0;

for (const page of pages) {
  const result = page.json && page.json.result;
  if (!Array.isArray(result)) {
    // an API error body, e.g. {"error": {"message": ...}, "status": "failure"}
    const apiError = page.json && page.json.error;
    if (apiError) {
      const msg = typeof apiError === 'string' ? apiError : apiError.message || JSON.stringify(apiError);
      throw new Error(`ServiceNow API error: ${msg}`);
    }
    // e.g. a hibernating instance returns an HTML page with HTTP 200
    throw new Error(
      'Unexpected ServiceNow response: no "result" array. The instance may be hibernating, ' +
        'or the account may be blocked by Basic Auth restrictions.'
    );
  }
  lastPageLength = result.length;
  for (const r of result) {
    const id = val(r.sys_id) || val(r.number);
    if (seen.has(id)) continue; // offset paging can overlap if records move between requests
    seen.add(id);
    incidents.push(r);
  }
}

// ---- 2. Refuse to act on a truncated list -----------------------------------------------
// Closing "cleared" alerts is only safe if we saw EVERY open incident. If we hit the page cap with
// a full last page there may be more, so fail loudly (the error workflow emails the admin).
if (pages.length >= maxPages && lastPageLength >= pageSize) {
  throw new Error(
    `Pagination cap reached (${maxPages} pages x ${pageSize} records) and more incidents may exist. ` +
      'Refusing to evaluate a partial incident list. Raise maxPages or narrow the query.'
  );
}

// ---- 3. Apply the alert rules -----------------------------------------------------------
const alerts = [];
for (const r of incidents) {
  const stateValue = String(val(r.state));
  if (CLOSED_STATES.includes(stateValue)) continue;

  const number = val(r.number);
  const priority = String(val(r.priority));
  const updatedMs = new Date(String(val(r.sys_updated_on)).replace(' ', 'T') + 'Z').getTime();
  const assignedTo = disp(r.assigned_to) || '';

  const types = [];
  if (priority === '1') types.push('critical');
  if (priority === '2' && cfg.alertHigh) types.push('high');
  if (Number.isFinite(updatedMs) && now - updatedMs >= staleMs) types.push('stale');

  // Someone has picked it up: In Progress (2) and assigned. Treated as an implicit acknowledgement.
  const autoAck = Boolean(cfg.autoAckOnProgress) && stateValue === '2' && assignedTo !== '';

  for (const alertType of types) {
    alerts.push({
      number,
      alertType,
      dedupKey: `${number}:${alertType}`,
      stateValue,
      autoAck,
      payload: {
        number,
        sysId: val(r.sys_id),
        priority: disp(r.priority),
        state: disp(r.state),
        assignedTo: assignedTo || 'Unassigned',
        description: disp(r.short_description),
        lastUpdated: `${val(r.sys_updated_on)} UTC`,
        link: `${cfg.instanceUrl}/nav_to.do?uri=incident.do?sys_id=${val(r.sys_id)}`,
        autoAck,
      },
    });
  }
}

return [
  {
    json: {
      alerts,
      incidentCount: incidents.length,
      pageCount: pages.length,
    },
  },
];

// Compares the alerts that apply NOW (Evaluate Rules) with the stored alert state (Load Alert State)
// and emits one "patch row" per write that has to happen. Every patch carries the NEW `version`;
// the Data Table update node only applies it if the stored row still has `version - 1`
// (compare-and-swap), which is what makes a claim atomic when two runs race.
//
// Patch rows come in three flavours (all written by the same CAS update):
//   claim        status 'pending' + claim_id = this run  -> an email will be sent for it
//   housekeeping resolve cleared alerts, apply auto-acknowledgements
//   new row      version 1 -> routed to an INSERT instead of an update
//
// Nothing to do  ->  returns [] and the run ends.
const cfg = $('Config').first().json;
const ev = $('Evaluate Rules').first().json;
const now = Date.now();
const nowIso = new Date(now).toISOString();
const MIN = 60 * 1000;
const claimId = cfg.runId;

const urgentMs = Number(cfg.reminderMinutesUrgent) * MIN; // critical / high
const staleReminderMs = Number(cfg.reminderHours) * 60 * MIN; // stale
const staleClaimMs = Number(cfg.staleClaimMinutes) * MIN;
const escalateTypes = String(cfg.escalateTypes || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
const levels = [1, 2]
  .map((n) => ({
    level: n,
    afterMs: Number(cfg['escalateL' + n + 'Minutes']) * MIN,
    to: String(cfg['escalateL' + n + 'Recipient'] || '').trim(),
  }))
  .filter((l) => l.to && Number.isFinite(l.afterMs) && l.afterMs > 0);

const ts = (v) => (v ? new Date(v).getTime() : 0);

function newToken() {
  try {
    return require('crypto').randomBytes(24).toString('hex'); // only if the runner allows it
  } catch (e) {
    let s = '';
    for (let i = 0; i < 4; i++) s += Math.random().toString(16).slice(2, 12).padEnd(10, '0');
    return s + now.toString(16);
  }
}

// ---- existing state, one row per key (if duplicates ever exist, the OLDEST row wins) ----------
const byKey = new Map();
for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.dedup_key || r.dedup_key === '__run_lock__') continue;
  const prev = byKey.get(r.dedup_key);
  if (!prev || Number(r.id) < Number(prev.id)) byKey.set(r.dedup_key, r);
}

// ---- notification policy ------------------------------------------------------------------
// For a row that has been notified at least once and is NOT acknowledged: what is due now?
function dueFor(row, a) {
  const first = ts(row.first_notified_at);
  const last = ts(row.last_notified_at) || first;
  const lvl = Number(row.escalation_level || 0);

  if (escalateTypes.includes(a.alertType)) {
    const next = levels.find((l) => l.level === lvl + 1);
    if (next && now - first >= next.afterMs) return { kind: 'escalation', level: next.level };
  }
  const interval = a.alertType === 'stale' ? staleReminderMs : urgentMs;
  if (now - last >= interval) return { kind: 'reminder', level: lvl };
  return null;
}

// A previous attempt failed or was abandoned: deliver now, regardless of the interval.
function retryKind(row, a) {
  if (!row.first_notified_at) return { kind: 'alert', level: 0 };
  const d = dueFor(row, a);
  if (d && d.kind === 'escalation') return d;
  return { kind: 'reminder', level: Number(row.escalation_level || 0) };
}

const housekeeping = [];
const claims = [];

function claimPatch(row, a, k, extra = {}) {
  return {
    dedup_key: a.dedupKey,
    incident_number: a.number,
    alert_type: a.alertType,
    incident_state: a.stateValue,
    payload: JSON.stringify(a.payload),
    status: 'pending',
    claim_id: claimId,
    claimed_at: nowIso,
    claim_kind: k.kind,
    claim_level: k.level,
    attempts: Number(row.attempts || 0) + 1,
    last_error: null,
    version: Number(row.version) + 1,
    ...extra,
  };
}

// ---- 1. alerts that apply now ----------------------------------------------------------------
for (const a of ev.alerts) {
  const row = byKey.get(a.dedupKey);

  if (!row) {
    claims.push({
      dedup_key: a.dedupKey,
      incident_number: a.number,
      alert_type: a.alertType,
      incident_state: a.stateValue,
      payload: JSON.stringify(a.payload),
      status: 'pending',
      claim_id: claimId,
      claimed_at: nowIso,
      claim_kind: 'alert',
      claim_level: 0,
      reminder_count: 0,
      escalation_level: 0,
      attempts: 1,
      ack_token: newToken(),
      version: 1, // version 1 = brand-new row -> INSERT
    });
    continue;
  }

  const acked = Boolean(row.acked_at);
  const everNotified = Boolean(row.first_notified_at);

  switch (row.status) {
    case 'resolved':
      // The condition came back (reopened / re-escalated): start a completely fresh cycle with a
      // new acknowledgement token, so an old email link cannot acknowledge the new occurrence.
      claims.push(
        claimPatch(row, a, { kind: 'alert', level: 0 }, {
          first_notified_at: null,
          last_notified_at: null,
          resolved_at: null,
          acked_at: null,
          acked_by: null,
          ack_source: null,
          ack_token: newToken(),
          reminder_count: 0,
          escalation_level: 0,
          attempts: 1,
        })
      );
      break;

    case 'pending':
      // Another run is mid-send - unless it died. A claim older than the threshold is abandoned,
      // so take it over directly (recover + claim in one compare-and-swap).
      if (now - ts(row.claimed_at) >= staleClaimMs) {
        if (acked && everNotified) {
          housekeeping.push({ dedup_key: a.dedupKey, status: 'sent', last_error: 'stale claim recovered', version: Number(row.version) + 1 });
        } else {
          claims.push(claimPatch(row, a, retryKind(row, a), { last_error: 'stale claim recovered' }));
        }
      }
      break;

    case 'failed':
      if (acked && everNotified) {
        // acknowledged while a reminder was failing: nothing left to retry
        housekeeping.push({ dedup_key: a.dedupKey, status: 'sent', version: Number(row.version) + 1 });
      } else {
        claims.push(claimPatch(row, a, retryKind(row, a)));
      }
      break;

    case 'sent': {
      if (acked) break; // acknowledged: no reminders, no escalation
      if (a.autoAck) {
        housekeeping.push({
          dedup_key: a.dedupKey,
          acked_at: nowIso,
          acked_by: 'ServiceNow (In Progress)',
          ack_source: 'servicenow',
          version: Number(row.version) + 1,
        });
        break;
      }
      const due = dueFor(row, a);
      if (due) claims.push(claimPatch(row, a, due));
      break;
    }

    default:
      break; // unknown status: leave it alone
  }
}

// ---- 2. close alerts whose condition no longer holds ------------------------------------------
// Resolved, downgraded, or updated-so-no-longer-stale. A later recurrence starts a fresh cycle.
const active = new Set(ev.alerts.map((a) => a.dedupKey));
for (const [key, row] of byKey) {
  if (active.has(key) || row.status === 'resolved') continue;
  const inFlight = row.status === 'pending' && now - ts(row.claimed_at) < staleClaimMs;
  if (inFlight) continue;
  housekeeping.push({ dedup_key: key, status: 'resolved', resolved_at: nowIso, version: Number(row.version) + 1 });
}

return [...housekeeping, ...claims].map((json) => ({ json }));

// Keeps only the claims THIS run owns and builds the email for each one.
//
// Ownership is re-checked against a fresh read of the table: if a lease failure ever let two runs
// INSERT the same brand-new key (Data Tables have no unique constraint), the row with the lowest id
// wins and the loser drops its claim here, before anything is sent.
const cfg = $('Config').first().json;
const fresh = $input.all().map((i) => i.json);

const oldestId = new Map();
for (const r of fresh) {
  if (!r || !r.dedup_key) continue;
  const cur = oldestId.get(r.dedup_key);
  if (cur === undefined || Number(r.id) < cur) oldestId.set(r.dedup_key, Number(r.id));
}

const TAG = {
  critical: '[CRITICAL INCIDENT]',
  high: '[HIGH PRIORITY INCIDENT]',
  stale: '[STALE INCIDENT REMINDER]',
};
const INTRO = {
  critical: 'A critical incident has been detected in ServiceNow.',
  high: 'A high-priority incident has been detected in ServiceNow.',
  stale: 'An incident has not been updated and is still unresolved.',
};

const seen = new Set();
const out = [];
for (const item of $('Merge Claims').all()) {
  const r = item.json;
  if (!r || r.status !== 'pending' || r.claim_id !== cfg.runId) continue;
  if (seen.has(r.dedup_key)) continue;
  if (oldestId.get(r.dedup_key) !== Number(r.id)) continue; // lost an insert race
  seen.add(r.dedup_key);

  let p = {};
  try {
    p = JSON.parse(r.payload || '{}');
  } catch (e) {
    p = {};
  }
  const kind = r.claim_kind || 'alert';
  const level = Number(r.claim_level || 0);
  const count = Number(r.reminder_count || 0);
  const minutesOpen = r.first_notified_at
    ? Math.round((Date.now() - new Date(r.first_notified_at).getTime()) / 60000)
    : 0;

  const to = [cfg.recipient];
  if (kind === 'escalation') {
    const extra = String(cfg['escalateL' + level + 'Recipient'] || '').trim();
    if (extra) to.push(extra);
  }

  const prefix = kind === 'escalation' ? `[ESCALATION L${level}] ` : kind === 'reminder' ? '[REMINDER] ' : '';
  const subject = `${prefix}${TAG[r.alert_type] || '[INCIDENT]'} ${p.number} — ${p.description}`;

  let intro = INTRO[r.alert_type] || 'An incident needs attention.';
  if (kind === 'reminder') {
    intro = `This incident is still unresolved and has not been acknowledged — reminder #${count + 1}.`;
  } else if (kind === 'escalation') {
    intro =
      `ESCALATION LEVEL ${level}: this incident has not been acknowledged ${minutesOpen} minutes ` +
      'after the first alert. Please take ownership now.';
  }

  const ackLine = cfg.ackBaseUrl
    ? `\nAcknowledge (stops reminders and escalation):\n${cfg.ackBaseUrl}?key=${encodeURIComponent(r.dedup_key)}&token=${r.ack_token}\n`
    : '';

  const text =
    `Hello Team,\n\n${intro}\n\n` +
    `- Incident: ${p.number}\n- Priority: ${p.priority}\n- Status: ${p.state}\n` +
    `- Assigned to: ${p.assignedTo}\n- Description: ${p.description}\n- Last updated: ${p.lastUpdated}\n\n` +
    'Please investigate this incident as soon as possible.\n\n' +
    `View incident: ${p.link}\n${ackLine}`;

  out.push({
    json: {
      dedup_key: r.dedup_key,
      claim_id: r.claim_id,
      kind,
      level,
      autoAck: Boolean(p.autoAck),
      to: to.join(','),
      subject,
      text,
      reminder_count: count,
      escalation_level: Number(r.escalation_level || 0),
      first_notified_at: r.first_notified_at || null,
    },
  });
}
return out;

// Turns each claim into its outcome row: 'sent' on success, 'failed' (retried next run) on error.
// A successful send is always recorded, even when other emails in the same batch failed, so one bad
// address cannot cause duplicate retries for incidents that were notified fine.
const claims = $('Select My Claims').all();
const nowIso = new Date().toISOString();
const out = [];

$input.all().forEach((item, i) => {
  const idx = item.pairedItem && item.pairedItem.item !== undefined ? item.pairedItem.item : i;
  const c = claims[idx].json;

  if (item.json && item.json.error) {
    const e = item.json.error;
    const message = typeof e === 'string' ? e : e.message || JSON.stringify(e);
    out.push({
      json: { dedup_key: c.dedup_key, claim_id: c.claim_id, status: 'failed', last_error: String(message).slice(0, 500) },
    });
    return;
  }

  const patch = {
    dedup_key: c.dedup_key,
    claim_id: c.claim_id,
    status: 'sent',
    first_notified_at: c.first_notified_at || nowIso,
    last_notified_at: nowIso,
    last_error: null,
    reminder_count: c.reminder_count + (c.kind === 'reminder' ? 1 : 0),
    escalation_level: c.kind === 'escalation' ? c.level : c.escalation_level,
  };
  if (c.autoAck) {
    patch.acked_at = nowIso;
    patch.acked_by = 'ServiceNow (In Progress)';
    patch.ack_source = 'servicenow';
  }
  out.push({ json: patch });
});

return out;

// Runs AFTER the outcomes are stored. If any email failed, raise an error so the error workflow
// notifies the administrator - the failed rows are already marked 'failed' and retry next run.
const outcomes = $('Resolve Claims').all().map((i) => i.json);
const failed = outcomes.filter((o) => o.status === 'failed');
if (failed.length > 0) {
  throw new Error(
    `${failed.length} alert email(s) failed to send (${failed.map((f) => f.dedup_key).join(', ')}); ` +
      'marked failed and will be retried next run. First error: ' + failed[0].last_error
  );
}
return [{ json: { sent: outcomes.length } }];
